// Rainflow wear and life estimate (#70, ff_wear_rainflow). The bandsplit fixture is generated by
// engine/test/fixtures/rainflow_bandsplit.py from research/analysis/depth/bandsplit.py (numpy; CI has none).
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdtempSync, readdirSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import type {
  BacktestResult,
  Bundle,
  HistDay,
  Plan,
  TorusPublished,
} from "@contracts/types";
import {
  clearlaneCyclesPerYr,
  histBundle,
  runBacktest,
  usableDay,
  windowDays,
} from "@engine/backtest";
import { solveDp } from "@engine/dp";
import { stableJson } from "@engine/json";
import { PULSE_LEVELS } from "@engine/limits";
import { solve } from "@engine/policies";
import {
  RAINFLOW_K,
  depthAwarePlan,
  depthSegMult,
  dwellHours,
  equivalentCycles,
  fullHours,
  raceFullHours,
  rainflow,
  socTrace,
  wearRainflow,
} from "@engine/rainflow";
import type { WearRainflow } from "@engine/rainflow";
import { referenceRace } from "@engine/reference";
import { defaultSite } from "@engine/site";
import { repoPath } from "./helpers/fixture";

const read = (p: string) => readFileSync(repoPath(p), "utf8");
const site = defaultSite();
const hist = JSON.parse(
  read("public/data/hist_2026-05-01_2026-10-27.json"),
) as HistDay[];
const torus = JSON.parse(
  read("public/data/torus_published.json"),
) as TorusPublished;
const backtest = JSON.parse(
  read("public/derived/backtest.json"),
) as BacktestResult;
const W = backtest.wear_usd_mwh;
const BUNDLE = "public/data/bundle_2026-10-27.json";
const bundle = JSON.parse(read(BUNDLE)) as Bundle;
const noMs = (p: Plan) => stableJson({ ...p, solve_ms: 0 });
const NOW = "2026-10-28T08:00:00Z";
const input = {
  hist,
  site,
  wear_usd_mwh: W,
  bundle,
  rated_cycles: torus.pulse_cycle_life.value,
  station_life_yr: torus.pulse_life_yr.value,
  sources: {
    hist: "public/data/hist_2026-05-01_2026-10-27.json",
    torus: "public/data/torus_published.json",
    backtest: "public/derived/backtest.json",
    bundle: BUNDLE,
  },
  generated_utc: NOW,
};
// Built once for the whole window: the report tests, the flag-off test and the CLI test share it.
const report = wearRainflow(input);
const pol = (p: string) => report.policies.find((x) => x.policy === p)!;

type Fixture = {
  traces: { name: string; x: number[]; cycles: [number, number][] }[];
  plateau: { x: number[]; cycles: [number, number][] };
};
const fixture = JSON.parse(
  read("engine/test/fixtures/rainflow_bandsplit.json"),
) as Fixture;

describe("3-point rainflow", () => {
  it.each(fixture.traces.map((t) => [t.name, t] as const))(
    "matches bandsplit.py on %s",
    (_, t) => {
      const ours = rainflow(t.x);
      expect(ours).toHaveLength(t.cycles.length);
      ours.forEach((c, i) => {
        expect(c.range).toBeCloseTo(t.cycles[i]![0], 12);
        expect(c.count).toBe(t.cycles[i]![1]);
      });
    },
  );

  it("counts a swing with a flat top, which bandsplit.py's turning points drop", () => {
    // bandsplit keeps both ends of the flat run and scores only zero-range cycles
    expect(fixture.plateau.cycles.every(([r]) => r === 0)).toBe(true);
    const ours = rainflow(fixture.plateau.x);
    expect(ours.reduce((a, c) => a + (c.range === 1 ? c.count : 0), 0)).toBe(1);
  });

  it.each([1, 2, 3, 6])(
    "counts exactly %i full cycles for that many identical full swings",
    (n) => {
      const swing = [0.25, 0.5, 0.75, 1, 1, 1, 0.75, 0.5, 0.25, 0, 0];
      const x = [0, ...Array.from({ length: n }, () => swing).flat()];
      const cycles = rainflow(x);
      expect(cycles.every((c) => c.range === 1)).toBe(true);
      expect(cycles.reduce((a, c) => a + c.count, 0)).toBe(n);
      for (const k of RAINFLOW_K)
        expect(equivalentCycles(cycles, 1, k)).toBe(n);
    },
  );
});

describe("Miner damage under N(DoD) = N_rated x DoD^-k", () => {
  it("one half-depth cycle is 0.5, 0.354 and 0.25 rated cycles at k 1, 1.5, 2", () => {
    const c = [{ range: 250, count: 1 }];
    expect(equivalentCycles(c, 500, 1)).toBe(0.5);
    expect(equivalentCycles(c, 500, 1.5)).toBeCloseTo(0.5 ** 1.5, 12);
    expect(equivalentCycles(c, 500, 2)).toBe(0.25);
    expect(RAINFLOW_K).toEqual([1, 1.5, 2]);
  });
});

describe("dwell above 80% and at full", () => {
  const fixed = solve(bundle, site, "fixed_overnight");

  it("interpolates inside an interval", () => {
    expect(dwellHours([0, 1], 0.8, 0.25)).toBeCloseTo(0.05, 12);
    expect(dwellHours([1, 1, 0.9], 0.8, 0.25)).toBe(0.5);
    expect(dwellHours([0.8, 0.8], 0.8, 0.25)).toBe(0);
  });

  it("the off-peak rule is above 80% for 14.2 h and full for 13 h on Oct 27", () => {
    const x = socTrace(fixed, site).map((s) => s / site.station.pulse_kwh);
    expect(dwellHours(x, 0.8, 0.25)).toBeCloseTo(14.2, 9);
    expect(fullHours(x, 0.25)).toBe(13);
  });

  it("habit.py's schedules hold Pulse full 13 h (off-peak rule) and 2 h (timetable) on Oct 27", () => {
    expect(raceFullHours(referenceRace(bundle))).toEqual({
      fixed_overnight: 13,
      timetable: 2,
    });
  });
});

describe("the depth-aware DP (segment approximation)", () => {
  it("segment multipliers are exactly 1 at k = 1 and average 1 over the full depth", () => {
    expect(depthSegMult(PULSE_LEVELS, 1).every((m) => m === 1)).toBe(true);
    const mean = (xs: number[]) => xs.reduce((a, x) => a + x, 0) / xs.length;
    expect(mean(depthSegMult(PULSE_LEVELS, 2))).toBeCloseTo(1, 12);
    expect(mean(depthSegMult(PULSE_LEVELS, 1.5))).toBeCloseTo(1, 3);
    const m2 = depthSegMult(PULSE_LEVELS, 2);
    // a shallow cycle near full is cheaper than a deep one near empty
    expect(m2[PULSE_LEVELS - 1]!).toBeLessThan(m2[0]!);
  });

  it("all-ones multipliers leave solveDp unchanged", () => {
    const base = {
      price: [10, 10, 50, 50],
      levels: 2,
      dz: 1,
      eta: 0.9,
      charge_max: [2, 2, 2, 2],
      discharge_max: [2, 2, 2, 2],
      W: 3,
      soc_min: 0,
      start_level: 0,
      end_level: 0,
      to_mwh: 1,
    };
    expect(solveDp({ ...base, seg_mult: [1, 1] })).toEqual(solveDp(base));
  });

  it("charges more for discharge deep in the battery when k > 1", () => {
    const base = {
      price: [0, 100],
      levels: 2,
      dz: 1,
      eta: 1,
      charge_max: [0, 0], // no charging, so the only way to value is down through the segments
      discharge_max: [1, 1],
      W: 10,
      soc_min: 0,
      start_level: 1,
      end_level: 0,
      to_mwh: 1,
    };
    // from level 1, selling at 100 crosses segment 0 (W x g x 3); from level 2 it crosses segment 1 (x 0.5)
    expect(solveDp({ ...base, seg_mult: [3, 0.5] }).objective).toBe(100 - 30);
    expect(
      solveDp({ ...base, seg_mult: [3, 0.5], start_level: 2 }).objective,
    ).toBe(100 - 5);
  });

  it("reduces to the linear wear price at k = 1: same plan, same value to the cent", () => {
    const byDay = new Map(hist.map((d) => [d.operating_day_mt, d]));
    const days = windowDays("2026-05-01", "2026-10-27")
      .map((d) => byDay.get(d))
      .filter(usableDay)
      .filter((_, i) => i % 18 === 0);
    const cases: [Bundle, "price_proxy" | undefined][] = [
      [bundle, undefined],
      ...days.map(
        (d) => [histBundle(d), "price_proxy"] as [Bundle, "price_proxy"],
      ),
    ];
    for (const [b, mode] of cases) {
      const lin = solve(b, site, "clearlane", {
        wear_usd_mwh: W,
        sch_mode: mode,
      });
      const dep = depthAwarePlan(b, site, W, 1, mode);
      expect(noMs(dep)).toBe(noMs(lin));
      expect(dep.value_usd.toFixed(2)).toBe(lin.value_usd.toFixed(2));
    }
  });
});

describe("the backtest report", () => {
  it("throughput cycles equal backtest.json's for every policy", () => {
    for (const p of backtest.policies)
      expect(pol(p.policy).throughput_cycles_per_yr).toBeCloseTo(
        p.pulse_cycles_per_yr,
        9,
      );
  });

  it("rated-cycle equivalents fall and life rises as k grows, for every policy", () => {
    for (const p of report.policies) {
      const eq = p.by_k.map((x) => x.equivalent_cycles_per_yr);
      expect(p.by_k.map((x) => x.k)).toEqual(RAINFLOW_K);
      for (let i = 1; i < eq.length; i++)
        expect(eq[i]!).toBeLessThanOrEqual(eq[i - 1]!);
      for (const x of p.by_k) {
        expect(x.life_prov).toBe("ASSUMPTION");
        expect(x.life_yr).toBeCloseTo(
          report.rating.pulse_cycle_life / x.equivalent_cycles_per_yr,
          9,
        );
      }
    }
  });

  it("at k = 1 rainflow agrees with throughput within 2%", () => {
    for (const p of report.policies) {
      const k1 = p.by_k[0]!.equivalent_cycles_per_yr;
      expect(Math.abs(k1 / p.throughput_cycles_per_yr - 1)).toBeLessThan(0.02);
    }
  });

  it("the off-peak rule dwells near full far longer than Clearlane", () => {
    expect(pol("fixed_overnight").dwell_h_above_80pct.mean).toBeGreaterThan(
      pol("clearlane").dwell_h_above_80pct.mean + 6,
    );
    expect(pol("fixed_overnight").full_h.p50).toBe(13);
  });

  it("the depth-aware Clearlane plan at k = 1 is the linear plan", () => {
    const k1 = report.depth_aware_clearlane[0]!;
    expect(k1.k).toBe(1);
    expect(k1.usd_per_mw_day.mean).toBe(
      backtest.policies.find((p) => p.policy === "clearlane")!.usd_per_mw_day
        .mean,
    );
    expect(k1.throughput_cycles_per_yr).toBeCloseTo(
      pol("clearlane").throughput_cycles_per_yr,
      9,
    );
  });

  it("names the flag, the calibrated W and the rating's assumptions, with no em dash", () => {
    expect(report.schema).toBe("clearlane.wear_rainflow/v1");
    expect(report.flag).toBe("ff_wear_rainflow");
    expect(report.wear_usd_mwh).toBe(10.95);
    expect(report.rating).toMatchObject({
      pulse_cycle_life: 7500,
      rated_dod: 1,
      rated_dod_prov: "ASSUMPTION",
    });
    expect(report.notes.join(" ")).toMatch(/Xu et al\. 2018.*UNVERIFIED/);
    expect(stableJson(report)).not.toContain(String.fromCharCode(0x2014));
  });
});

describe("flag off (ff_wear_rainflow): core outputs are byte-identical", () => {
  it("after the report runs, the backtest still reproduces backtest.json and backtest_days.json", () => {
    expect(report.policies).toHaveLength(3);
    const run = runBacktest(hist, site, {
      wear_usd_mwh: W,
      seed: backtest.seed,
      by_hour: torus.events_2025_by_hour.value,
      by_weekday: torus.events_2025_by_weekday.value,
    });
    expect(stableJson(run.result)).toBe(read("public/derived/backtest.json"));
    expect(stableJson(run.days)).toBe(
      read("public/derived/backtest_days.json"),
    );
  }, 120_000);

  it("the wear calibration still lands on $10.95: within budget there, over it a cent below", () => {
    expect(clearlaneCyclesPerYr(hist, site, 10.95)).toBeLessThanOrEqual(300);
    expect(clearlaneCyclesPerYr(hist, site, 10.94)).toBeGreaterThan(300);
  }, 120_000);

  it("the numbers CLI reproduces numbers.json byte for byte", () => {
    const out = join(mkdtempSync(join(tmpdir(), "rf-num-")), "numbers.json");
    execFileSync(
      process.execPath,
      [
        "--import",
        "tsx",
        repoPath("engine/cli/numbers.ts"),
        BUNDLE,
        "--out",
        out,
      ],
      { cwd: repoPath("."), encoding: "utf8" },
    );
    expect(readFileSync(out, "utf8")).toBe(read("public/derived/numbers.json"));
  }, 120_000);

  it("no core module or core CLI imports the rainflow code", () => {
    const core = [
      ...readdirSync(repoPath("engine/src"))
        .filter((f) => f !== "rainflow.ts")
        .map((f) => `engine/src/${f}`),
      ...readdirSync(repoPath("engine/cli"))
        .filter((f) => f !== "wear.ts")
        .map((f) => `engine/cli/${f}`),
    ];
    expect(core.filter((f) => /\/rainflow["']/.test(read(f)))).toEqual([]);
  });
});

describe("engine/cli/wear.ts", () => {
  const CURVE = "public/derived/wear_rainflow.json";
  const hashes = () => {
    const dir = repoPath("public/derived");
    return Object.fromEntries(
      readdirSync(dir)
        .sort()
        .map((f) => [
          f,
          createHash("sha256")
            .update(readFileSync(join(dir, f)))
            .digest("hex"),
        ]),
    );
  };

  it("writes only its --out file, equal to the in-process report for the same --now", () => {
    const before = hashes();
    const out = join(mkdtempSync(join(tmpdir(), "rf-cli-")), "wear.json");
    execFileSync(
      process.execPath,
      [
        "--import",
        "tsx",
        repoPath("engine/cli/wear.ts"),
        "--out",
        out,
        "--now",
        NOW,
      ],
      { cwd: repoPath("."), encoding: "utf8" },
    );
    expect(hashes()).toEqual(before);
    expect(readFileSync(out, "utf8")).toBe(stableJson(report));
  }, 120_000);

  it.skipIf(!existsSync(repoPath(CURVE)))(
    "public/derived/wear_rainflow.json equals the report for its generated_utc",
    () => {
      const text = read(CURVE);
      const onDisk = JSON.parse(text) as WearRainflow;
      expect(text).toBe(
        stableJson({ ...report, generated_utc: onDisk.generated_utc }),
      );
    },
  );
});
